from collections import Counter
def f(I):
    H,W=len(I),len(I[0]); bg=Counter(x for r in I for x in r).most_common(1)[0][0]
    # candidate rects: solid uniform blocks not bg; pick largest area
    best=None
    for r in range(H):
        for c in range(W):
            v=I[r][c]
            if v==bg: continue
            h=[i for i in range(r,H) if I[i][c]==v]; w=[j for j in range(c,W) if I[r][j]==v]
            if len(h)*len(w)> (best is None or 0): 
                pass
    # simpler: scan full rectangles by color extents
    for v in set(x for r in I for x in r)-{bg}:
        rows=[i for i in range(H) if any(I[i][j]==v for j in range(W))]
        cols=[j for j in range(W) if any(I[i][j]==v for i in range(H))]
        rs=[i for i in rows if all(I[i][j]==v for j in cols)]
        if rs and all(all(I[i][j]==v for j in cols) for i in rs):
            area=(max(rs)-min(rs)+1)*(max(cols)-min(cols)+1)
            if best is None or area>best[0]: best=(area,v,min(rs),max(rs),min(cols),max(cols))
    area,v,r0,r1,c0,c1=best
    O=[row[:] for row in I]
    for i in range(H):
        for j in range(W):
            v2=I[i][j]
            if v2==bg or (r0<=i<=r1 and c0<=j<=c1): continue
            if c0<=j<=c1 and (i<r0 or i>r1):
                ti = r0 if i<r0 else r1; O[ti][j]=v2
            elif r0<=i<=r1 and (j<c0 or j>c1):
                tj = c0 if j<c0 else c1; O[i][tj]=v2
            else:
                O[i][j]=v2
    return O
